// Generated by scripts/build-sensing-ui.py from the approved visual design.
export async function get(url){const r=await fetch(url);const body=await r.json();if(!r.ok)throw Error(body.error||body.message||'数据读取失败');return body;}
function sourcePayload(subs,rss){return {subscriptions:(subs.list||[]).map(s=>({...s,platform:s.payload?.platform||((s.id||'').startsWith('x:')?'x':'mp'),name:s.payload?.name||s.name||s.id,lastSync:s.last_sync,historyCount:s.legacy_count})),jobs:subs.jobs||[],rss};}
export async function loadSensingPayload(view,query){const raw=await get('api/data'+query);let catalog={},ruleError=null;try{catalog=await get('quant/api/catalog'+query);}catch(e){ruleError=e.message;}const extra=view==='sources'?sourcePayload(...await Promise.all([get('/api/subscriptions'),get('/api/rss/sources')])):{subscriptions:[],jobs:[],rss:{list:[]}};return {...extra,documents:catalog.documents||raw.documents,sources:raw.sources,topics:raw.topics,collection:raw.collection,processing:raw.processing,snapshotAt:raw.generatedAt,downloadedAt:raw.generatedAt,ruleError,rulePublication:catalog.ruleSnapshot?.industryRulePublication};}
export function mountSensing(root,payload,selectedView){
const life=new AbortController(),document={querySelector:s=>root.querySelector(s),querySelectorAll:s=>root.querySelectorAll(s),body:root.querySelector('.sensing-shell')},location={hash:selectedView==='library'?'#evidence':'#sources'};
const listen=(type,callback)=>root.addEventListener(type,callback,{signal:life.signal});
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={'海洋油气':'海洋油气','海上风电':'海洋新能源','海洋新能源':'海洋新能源','海洋低碳':'海洋低碳','多能融合':'多能融合','宏观政策':'宏观政策','海洋装备':'海洋装备'};
const topics=['海洋油气','海上风电','海洋低碳','多能融合','宏观政策','海洋装备'];
const statusNames={accepted:'纳入行业',excluded:'反向排除',unmatched:'待进一步判断'};
const date=v=>{if(!v)return '暂无记录';const d=new Date(v);return Number.isNaN(+d)?String(v):new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d);};
const day=v=>{if(!v||Number.isNaN(Date.parse(v)))return null;return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));};
const urlLink=(url,label)=>/^https?:\/\//i.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);
const phases=['pipeline','scanner','constellation'];
let phase=0,evidenceQuery='',evidencePageNumber=1,evidencePageSize=12;
let data,view='sources',channel='all',search='',page=1,tab='channels',effect='pipeline',sector='',sourceFilter='',paused=false,finished=false,step=0,timer,charts=[],resize,toastTimer;
const source=id=>data.sources.find(s=>s.id===id)?.name||id||'未标注渠道';
const docs=()=>data.documents.filter(d=>(!sector||(d.classification?.primary||d.topic)===sector)&&(!sourceFilter||d.sourceId===sourceFilter));
const topicColors=['#78cfc3','#a997ee','#7db9dd','#e0b874','#d998af','#82b995'];
const topicColor=t=>topicColors[topics.indexOf(t)]||'#94abc0';
const matchedTopic=d=>d.classification?.primary||d.classification?.positive?.find(p=>topics.includes(p.topic))?.topic;
function samples(){const all=docs().filter(d=>topics.includes(matchedTopic(d))),accepted=all.filter(d=>d.classification?.status==='accepted'&&keywords(d).length),excluded=all.filter(d=>d.classification?.status==='excluded'&&negative(d).length&&keywords(d).length),out=[];
 if(accepted[0])out.push(accepted[0]);if(excluded[0])out.push(excluded[0]);
 const another=accepted.find(d=>!out.includes(d)&&matchedTopic(d)!==matchedTopic(out[0]||{}))||accepted.find(d=>!out.includes(d));if(another)out.push(another);
 return out;
}
function keywordTags(d,kind){const values=kind==='positive'?keywords(d):negative(d);return values.length?values.map(k=>`<span class="keyword ${kind}">${kind==='positive'?'+':'−'} ${esc(k)}</span>`).join(''):`<span class="muted">${kind==='positive'?'无正向命中记录':'未命中反向词'}</span>`;}
function industryTag(d){const t=matchedTopic(d);return `<span class="industry-tag" style="--industry:${topicColor(t)}">${esc(names[t]||'')} ${d.classification?.status==='excluded'?'· 匹配后排除':''}</span>`;}

function stat(label,value,note){return `<div class="stat"><span>${label}</span><b>${esc(value)}</b><small>${esc(note)}</small></div>`;}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3600);}
function dispose(){clearInterval(timer);charts.forEach(c=>c.dispose());charts=[];resize?.disconnect();}
function render(){dispose();view=location.hash==='#evidence'?'evidence':'sources';$('#page-title').textContent=view==='sources'?'全球信息感知 / '+({channels:'渠道管理',add:'添加订阅',jobs:'同步记录'}[tab]):'情报证据中心';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===view));$('#app').innerHTML=view==='sources'?sourcesPage():evidencePage();if(view==='evidence'&&!data.ruleError){finished=matchMedia('(prefers-reduced-motion: reduce)').matches;paused=false;step=0;phase=0;effect=phases[0];startReplay();}}
function allChannels(){const subs=data.subscriptions.map(s=>({...s,type:s.platform==='x'?'x':'mp',name:s.name,count:Number(s.count||0),ready:Number(s.ready||0),historyCount:Number(s.historyCount||0),date:s.latest,url:'',status:s.enabled===false?'暂停':'已订阅',note:s.platform==='x'?'推文与外链文章':'公众号文章'}));const rss=(data.rss?.list||[]).map(s=>({...s,type:s.method==='rss'?'rss':'official',url:s.alias||s.url,date:s.checkedAt,ready:null,status:({ready:'检查成功',partial:'部分成功',failed:'访问失败',unverified:'待检查'})[s.status]||s.status||'待检查',note:s.scope||s.method||'RSS'}));return [...subs,...rss];}
function sourcesPage(){const channels=allChannels(),subs=data.subscriptions,counts={mp:channels.filter(s=>s.type==='mp').length,x:channels.filter(s=>s.type==='x').length,rss:channels.filter(s=>s.type==='rss').length,official:channels.filter(s=>s.type==='official').length};return `<section class="intro"><div><p class="eyebrow">GLOBAL SENSING / CONNECTED SOURCES</p><h1>全球信息感知</h1><p>将公众号、X、RSS 与官方数据放在同一张工作台。看见来源、采集状态，以及每条资料的下一站。</p><span class="snapshot">数据快照 ${date(data.downloadedAt)} · 所有时间为北京时间</span></div><div class="signal" aria-hidden="true"></div></section><div class="stats">${stat('公众号与 X 订阅',subs.length,`${counts.mp} 个公众号 · ${counts.x} 个 X 账号`)}${stat('RSS 与官方渠道',counts.rss+counts.official,`${counts.rss} 个 RSS · ${counts.official} 个网页／数据渠道`)}${stat('订阅平台收录文章',subs.reduce((n,s)=>n+Number(s.count||0),0),'含待分类与未取得正文的记录')}${stat('已进入智库',data.documents.length,'入库文章快照 · 与平台收录口径不同')}</div><section class="panel"><div class="panel-head"><div class="tabs">${[['channels','渠道管理'],['add','添加订阅'],['jobs','同步记录']].map(([id,t])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${t}</button>`).join('')}</div><a href="#library">查看分类与清洗 →</a></div><div id="channel-content">${channelContent()}</div></section><div class="split"><section class="panel"><p class="eyebrow">COLLECTION CADENCE</p><h2>不同渠道，各自有序更新</h2><p class="hint">公众号 / X：每轮完成后间隔 30 分钟<br>外部资讯渠道：定时巡检约 6 小时<br>官方工作簿：依渠道计划检查版本</p><p class="muted">以上是采集机制说明。采集进度与执行结果以同步记录为准。</p></section><section class="panel"><p class="eyebrow">FROM SOURCE TO EVIDENCE</p><h2>资料进入智库的路径</h2><p class="hint">发现文章 → 获取正文 → 清理噪声 → 行业归类 → 关联证据</p><p class="muted">订阅数量、平台收录文章、智库入库文档分别计数，不相加。来源管理与分类结果分开呈现。</p><a href="#library">进入情报证据中心 →</a></section></div>`;}
function channelContent(){if(tab==='add')return addForm();if(tab==='jobs')return `<p class="hint">最近同步任务及执行状态。</p><div class="table-wrap"><table><thead><tr><th>任务</th><th>操作</th><th>状态</th><th>创建时间</th></tr></thead><tbody>${data.jobs.map(j=>`<tr><td>#${esc(j.id)}</td><td>${esc(({sync_all:'全量同步',sync_one:'单渠道同步',batch_discover:'批量发现',refresh:'更新账号列表'})[j.action]||j.action)}</td><td><span class="tag">${esc(({completed:'已完成',running:'执行中',queued:'排队中',failed:'未完成'})[j.status]||j.status)}</span></td><td>${date(j.created_at)}</td></tr>`).join('')||'<tr><td colspan="4">暂无同步记录</td></tr>'}</tbody></table></div>`;const rows=allChannels(),count=t=>rows.filter(s=>t==='all'||s.type===t).length;return `<div class="toolbar"><div class="tabs">${[['all','全部渠道'],['mp','公众号'],['x','X'],['rss','RSS'],['official','官方网页 / 数据']].map(([id,label])=>`<button data-channel="${id}" class="${channel===id?'active':''}">${label}<em>${count(id)}</em></button>`).join('')}</div></div><div class="toolbar"><input type="search" id="channel-search" placeholder="搜索渠道名称或地址" value="${esc(search)}" aria-label="搜索渠道"><div class="tools"><button data-action="refresh">更新账号列表</button><button data-action="sync" class="primary">同步公众号与 X</button></div></div><div id="channel-table">${channelTable()}</div>`;}
function channelTable(){const rows=allChannels().filter(s=>(channel==='all'||s.type===channel)&&`${s.name} ${s.url}`.toLowerCase().includes(search.toLowerCase())),pages=Math.max(1,Math.ceil(rows.length/8));page=Math.min(page,pages);return `<div class="table-wrap"><table><thead><tr><th>来源与渠道</th><th>收录 / 正文</th><th>最近时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.slice((page-1)*8,page*8).map(s=>`<tr><td><div class="channel-name"><span class="channel-icon">${{mp:'微',x:'X',rss:'RSS',official:'◈'}[s.type]}</span><div><strong>${esc(s.name)}</strong><small>${{mp:'微信公众号',x:'X 社交渠道',rss:'RSS 订阅',official:'官方网页 / 数据'}[s.type]}</small></div></div></td><td>${s.count} 篇${s.ready!==null?`<small> / 正文 ${s.ready}</small><div class="mini-track"><i style="width:${s.count?Math.min(100,s.ready/s.count*100):0}%"></i></div><small>历史文章 ${s.historyCount||0} 篇 · 单列</small>`:'<br><small>当前渠道文章记录</small>'}</td><td>${date(s.date)}<br><small>${s.ready!==null?'最新文章发布日期':'最近渠道检查'}</small></td><td><span class="status-dot"></span>${esc(s.status)}</td><td><button data-channel-detail="${esc(s.id)}">查看详情</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">没有匹配的渠道</td></tr>'}</tbody></table></div><div class="pagination"><span>${rows.length} 个渠道 · ${page} / ${pages} 页</span><button data-page-change="-1" ${page===1?'disabled':''}>上一页</button><button data-page-change="1" ${page===pages?'disabled':''}>下一页</button></div>`;}
function addForm(){return `<form id="add-form" class="form-grid" style="margin-top:20px"><label>渠道类型<select id="new-type"><option value="mp">微信公众号</option><option value="rss">RSS</option></select></label><label>公众号文章链接或 RSS 地址<input id="new-source" type="url" required placeholder="https://"></label><label>RSS 名称（添加 RSS 时必填）<input id="new-name"></label><button type="submit" class="primary">添加订阅</button><p class="hint">公众号通过原始文章链接校验身份；RSS 保存名称和订阅地址。X 账号及批量发现请使用<a href="/wechat/subscriptions">订阅高级管理 ↗</a>。</p></form>`;}


function classificationTags(d){const c=d.classification||{},kind=c.status==='accepted'?'positive':c.status==='excluded'?'negative':'';return `<span class="keyword ${kind}">${esc(statusNames[c.status]||'未记录')}</span> ${matchedTopic(d)?industryTag(d):'<span class="muted">暂无主行业</span>'}`;}
function evidenceResults(){
 const terms=evidenceQuery.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
 const rows=docs().filter(d=>{const c=d.classification||{},text=[d.title,source(d.sourceId),names[c.primary],names[matchedTopic(d)],statusNames[c.status],c.reason,...keywords(d),...negative(d)].filter(Boolean).join(' ').toLocaleLowerCase();return terms.every(term=>text.includes(term));});
 const totalPages=Math.max(1,Math.ceil(rows.length/evidencePageSize));evidencePageNumber=Math.max(1,Math.min(evidencePageNumber,totalPages));
 return `<div class="evidence-list">${rows.slice((evidencePageNumber-1)*evidencePageSize,evidencePageNumber*evidencePageSize).map(d=>`<article class="evidence-item"><button data-evidence="${esc(d.id)}">分类依据 ↗</button><div class="meta">${esc(source(d.sourceId))} · ${date(d.publishedAt)}</div><b>${esc(d.title)}</b><div class="classification-tags">${classificationTags(d)}</div><p>${esc(d.classification?.reason||'没有分类原因记录')}</p></article>`).join('')||'<p class="empty">没有匹配资料，请调整搜索词或上方筛选条件。</p>'}</div><div class="pagination" aria-label="分类依据分页"><span role="status">共 ${rows.length} 条 · 第 ${rows.length?evidencePageNumber:0} / ${rows.length?totalPages:0} 页</span><button data-evidence-page="-1" ${evidencePageNumber<=1?'disabled':''}>上一页</button><button data-evidence-page="1" ${evidencePageNumber>=totalPages?'disabled':''}>下一页</button></div>`;
}

function evidencePage(){if(data.ruleError)return `<section class="panel" role="alert"><h1>分类规则暂不可用</h1><p>${esc(data.ruleError)}</p><p>请同步数据快照后重新打开，旧分类动画与汇总已停止展示。</p></section>`;const all=docs(),accepted=all.filter(d=>d.classification?.status==='accepted').length;return `<section class="intro"><div><p class="eyebrow">EVIDENCE CENTER / CLASSIFICATION REPLAY</p><h1>让情报的形成过程可见</h1><p>从多源资讯到六大行业，沿着已有证据回看清洗、规则匹配与分类结果。</p><span class="snapshot">入库快照 ${date(data.snapshotAt)} · 数据库已生效规则 ${esc(data.rulePublication?.version||'未记录')} · 分类结果回放</span></div><span class="tag">分类回放 · 不重新调用模型</span></section><div class="toolbar"><div class="tools"><select id="sector" aria-label="筛选行业"><option value="">全部行业</option>${topics.map(t=>`<option value="${t}" ${sector===t?'selected':''}>${names[t]}</option>`).join('')}</select><select id="evidence-source" aria-label="筛选来源"><option value="">全部渠道来源</option>${data.sources.filter(s=>data.documents.some(d=>d.sourceId===s.id)).map(s=>`<option value="${esc(s.id)}" ${sourceFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><span class="muted">筛选同时作用于回放样本、图表与依据清单</span></div><div class="stats">${stat('当前范围文章',all.length,'一篇文章计一次，不等于行业规模')}${stat('纳入行业',accepted,'通过行业分类的文章')}${stat('反向排除',all.filter(d=>d.classification?.status==='excluded').length,'保留命中原因及原始来源')}${stat('待进一步判断',all.filter(d=>d.classification?.status==='unmatched').length,'未命中不代表无价值或无关')}</div><div id="summary" hidden></div><div id="workflow"><div class="option-grid">${[['pipeline','01 / FLOW','流水线分拣','看来源、匹配与分类之间的流转'],['scanner','02 / SCAN','原文扫描','逐条呈现真实关键词和命中依据'],['constellation','03 / ORBIT','行业归类连线','观察资讯向六个行业归集']].map(([id,n,t,desc])=>`<button data-effect="${id}" class="effect-choice ${effect===id?'active':''}" aria-pressed="${effect===id}"><div class="effect-no">${n}</div><b>${t}</b><small>${desc}</small></button>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>资讯清洗工作流</h2><span class="muted">分拣 → 扫描 → 归类，约 ${Math.round(samples().length*3*2.2)} 秒回放 ${samples().length} 条有关键词依据的案例；汇总覆盖当前全部 ${all.length} 篇。</span></div><div class="tools"><button id="pause">暂停</button><button id="replay">重放清洗</button><button id="skip">跳过动画，查看汇总</button></div></div><div class="progress" aria-hidden="true"><i id="progress-fill"></i></div><div id="stage" class="stage"></div><div id="replay-detail" class="stage-detail" aria-live="polite"></div></section></div><section class="panel"><div class="panel-head"><div><p class="eyebrow">TRACEABLE DECISIONS</p><h2>分类依据清单</h2></div><span class="muted">搜索当前筛选范围内的全部资料 · 点击核对完整依据</span></div><div class="toolbar"><input id="evidence-search" type="search" aria-label="搜索分类依据" placeholder="搜索标题、渠道、行业或命中关键词" value="${esc(evidenceQuery)}"><label>每页 <select id="evidence-page-size" aria-label="每页依据数量">${[12,24,48].map(n=>`<option value="${n}" ${evidencePageSize===n?'selected':''}>${n} 条</option>`).join('')}</select></label></div><div id="evidence-results">${evidenceResults()}</div></section>`;}
function keywords(d){return (d.classification?.positive||[]).flatMap(p=>(p.keywords||[]).map(k=>typeof k==='string'?k:k.keyword)).filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).slice(0,7);}
function negative(d){return (d.classification?.negative||[]).map(k=>typeof k==='string'?k:k.keyword).filter(Boolean);}
function stageMarkup(d){
 const c=d.classification||{},rejected=c.status==='excluded',t=matchedTopic(d),result=statusNames[c.status],header=`<div class="stage-top"><span>${finished?'工作流完成':'● 阶段 '+(phase+1)+' / 3'} · 样本 ${step+1} / ${samples().length}</span><span>已存分类结果 · ${esc(source(d.sourceId))}</span></div>`;
 const ruleBlock=`<div class="rule-group"><small>正向关键词命中</small><div class="keyword-list">${keywordTags(d,'positive')}</div></div><div class="rule-group"><small>反向过滤关键词</small><div class="keyword-list">${keywordTags(d,'negative')}</div></div>`;
 if(effect==='pipeline')return header+`<div class="flow"><div class="flow-node"><small>01 / SOURCE</small><b>${esc(source(d.sourceId))}</b><span class="muted">${esc(d.title.slice(0,64))}</span></div><div class="flow-wire"></div><div class="flow-node focus"><small>02 / MATCH</small><b>关键词匹配与过滤</b>${ruleBlock}</div><div class="flow-wire"></div><div class="flow-node"><small>03 / CLASSIFY</small><b class="${rejected?'negative-text':'positive-text'}">${esc(result)}</b>${industryTag(d)}<p class="muted">${rejected?'虽然命中行业词，反向规则将其排除；不计入纳入行业统计。':'通过行业规则，计入对应行业。'}</p></div></div>`;
 if(effect==='scanner')return header+`<div class="scan"><div class="scan-paper"><small class="muted">原始文章标题</small><h3>${esc(d.title)}</h3><p>${esc(c.reason)}</p>${ruleBlock}</div><div><p class="eyebrow">MATCHED EVIDENCE</p><h2 class="${rejected?'negative-text':'positive-text'}">${esc(result)}</h2>${industryTag(d)}<p class="muted">${rejected?'反向词来自已存规则匹配记录，优先阻止此条资料纳入；匹配行业不等于最终纳入行业。':esc(c.primaryBasis||'按已有分类记录展示。')}</p><span class="tag">${esc(c.version||'分类版本未标注')}</span></div></div>`;
 const xy=[[20,20],[80,20],[90,50],[80,80],[20,80],[10,50]];
 return header+`<div class="radial"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${xy.map(([x,y],i)=>`<line x1="50" y1="50" x2="${x}" y2="${y}" style="stroke:${topics[i]===t?(rejected?'var(--negative)':topicColors[i]):topicColors[i]};stroke-opacity:${topics[i]===t?1:.25};stroke-width:${topics[i]===t?2:1}" vector-effect="non-scaling-stroke"/>`).join('')}</svg><div class="radial-center"><span class="muted">${esc(source(d.sourceId))}</span><b class="${rejected?'negative-text':'positive-text'}">${esc(result)}</b></div>${topics.map((topic,i)=>`<div class="orbit-label ${topic===t?'lit':''}" style="left:${xy[i][0]}%;top:${xy[i][1]}%;--industry:${topicColors[i]}">${names[topic]}${topic===t&&rejected?'<small>匹配后排除</small>':''}</div>`).join('')}</div><div class="orbit-keywords">${ruleBlock}</div>`;
}

function paintReplay(){document.querySelectorAll('[data-effect]').forEach(b=>{const n=phases.indexOf(b.dataset.effect);b.classList.toggle('active',n===phase);b.classList.toggle('complete',finished||n<phase);b.setAttribute('aria-pressed',String(n===phase));});const chosen=samples();if(!chosen.length){$('#stage').innerHTML='<p class="empty">当前范围没有符合条件的关键词命中案例</p>';$('#replay-detail').textContent='仅回放有行业匹配与正向／反向词依据的案例；未命中记录仍保留在分类汇总。';finished=true;clearInterval(timer);$('#pause').disabled=true;$('#progress-fill').style.width='100%';showSummary();return;}const d=chosen[Math.min(step,chosen.length-1)];$('#stage').innerHTML=stageMarkup(d);$('#stage').classList.toggle('paused',paused);$('#stage').classList.toggle('done',finished);$('#progress-fill').style.width=(finished?100:(phase*chosen.length+step+1)/(chosen.length*3)*100)+'%';$('#replay-detail').innerHTML=`<span class="keyword positive">+ 正向命中</span> <span class="keyword negative">− 反向排除</span> ${industryTag(d)}<br><b>${finished?'回放完成':'当前资料'}：</b>${esc(d.title)}<br><span class="muted">${esc(d.classification?.reason||'暂无分类依据')} · ${finished?'页面上方已展示当前全部筛选结果的分类汇总。':'这里只回放已存结果；未实际重新执行清洗或分类。'}</span>`;$('#pause').textContent=paused?'继续播放':'暂停';$('#pause').disabled=finished;}
function completeWorkflow(){
 const box=$('#workflow').getBoundingClientRect(),watching=box.top<innerHeight&&box.bottom>0;
 finished=true;clearInterval(timer);paintReplay();showSummary();
 if(watching&&!matchMedia('(prefers-reduced-motion: reduce)').matches)requestAnimationFrame(()=>$('#summary').scrollIntoView({behavior:'smooth',block:'start'}));
}
function startReplay(){clearInterval(timer);effect=phases[phase];paintReplay();if(finished){showSummary();return;}timer=setInterval(()=>{
 if(paused||document.hidden)return;
 if(step<samples().length-1)step++;
 else if(phase<2){phase++;effect=phases[phase];step=0;}
 else{completeWorkflow();return;}
 paintReplay();
},2200);}

function chart(id,option){const el=$('#'+id);if(!el)return;const light=document.body.classList.contains('light'),c=echarts.init(el,null,{renderer:'canvas'});c.setOption({backgroundColor:'transparent',color:topicColors,textStyle:{color:light?'#335269':'#a9bdcd',fontFamily:'Segoe UI, Microsoft YaHei'},tooltip:{trigger:'item',confine:true},...option});charts.push(c);resize.observe(el);}
function showSummary(){$('#summary').hidden=false;charts.forEach(c=>c.dispose());charts=[];resize?.disconnect();const all=docs(),accepted=all.filter(d=>d.classification?.status==='accepted');$('#summary').innerHTML=`<div class="summary-head"><p class="eyebrow">CLASSIFICATION COMPLETE / SNAPSHOT SUMMARY</p><h2>分类汇总 · ${all.length} 篇真实资料</h2><p>回放已结束。以下统计覆盖当前筛选范围，文章数量反映资料覆盖，不代表产量、投资额或产业规模。</p></div><div class="charts-grid"><section class="panel"><h3>六大行业 · 纳入资料分布</h3><div id="industry-chart" class="chart" aria-label="行业文章数量图"></div><p class="chart-note">按文章主行业计数，每篇只计一次；排除与未命中不计入。</p></section><section class="panel"><h3>分类去向 · 原始资料保留</h3><div id="status-chart" class="chart" aria-label="分类状态分布图"></div><p class="chart-note">纳入、排除与待判断互斥；资料不因排除而被删除。</p></section><section class="panel"><h3>发布节奏 · 最近 90 天</h3><div id="time-chart" class="chart" aria-label="文章发布日历热力图"></div><p class="chart-note">截止当前范围最新已知发布日期，按北京时间逐日计数；空格表示本快照未收录，不代表当天没有事件。</p></section><section class="panel"><h3>渠道 → 行业 · 覆盖流向</h3><div id="flow-chart" class="chart" aria-label="来源到行业的桑基图"></div><p class="chart-note">展示纳入文章最多的 6 个渠道，其余合并为其他渠道；连线宽度为文章数。</p></section></div>`;resize=new ResizeObserver(entries=>entries.forEach(e=>echarts.getInstanceByDom(e.target)?.resize()));
 const counts=topics.map(t=>({name:names[t],value:accepted.filter(d=>d.classification?.primary===t).length}));chart('industry-chart',{grid:{left:95,right:30,top:22,bottom:30},xAxis:{type:'value',minInterval:1,splitLine:{lineStyle:{color:'#819bad22'}}},yAxis:{type:'category',data:counts.map(c=>c.name),axisTick:{show:false}},series:[{type:'bar',barMaxWidth:18,data:counts.map((c,i)=>({value:c.value,itemStyle:{color:topicColors[i],borderRadius:[0,4,4,0]}})),label:{show:true,position:'right',color:'inherit'}}]});
 chart('status-chart',{legend:{bottom:0,textStyle:{color:document.body.classList.contains('light')?'#335269':'#a9bdcd'}},series:[{type:'pie',radius:['45%','68%'],center:['50%','45%'],label:{show:true,formatter:'{c} 篇',color:'inherit'},data:['accepted','excluded','unmatched'].map(s=>({name:statusNames[s],value:all.filter(d=>d.classification?.status===s).length}))}]});
 const dated=all.map(d=>day(d.publishedAt)).filter(Boolean).sort(),end=dated.at(-1),byDay=new Map();dated.forEach(d=>byDay.set(d,(byDay.get(d)||0)+1));if(end){const start=new Date(end+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-89);const begin=start.toISOString().slice(0,10),rows=[...byDay].filter(([d])=>d>=begin);chart('time-chart',{tooltip:{formatter:p=>`${esc(p.value[0])}：${p.value[1]} 篇`},calendar:{top:55,left:42,right:20,bottom:70,range:[begin,end],cellSize:['auto',23],splitLine:{show:false},yearLabel:{show:false},dayLabel:{firstDay:1,nameMap:'cn',color:'#91a7ba'},monthLabel:{nameMap:'cn',color:'#91a7ba'},itemStyle:{color:document.body.classList.contains('light')?'#eaf2f7':'#192e3e',borderColor:document.body.classList.contains('light')?'#cbdce6':'#294451',borderWidth:1}},visualMap:{min:0,max:Math.max(1,...rows.map(r=>r[1])),orient:'horizontal',bottom:5,left:'center',text:['较多','较少'],textStyle:{color:'#91a7ba'},inRange:{color:['#284b5e','#438e99','#98ddd6']}},series:[{type:'heatmap',coordinateSystem:'calendar',data:rows}]});}else $('#time-chart').innerHTML='<p class="empty">没有有效发布日期</p>';
 const sourceCounts=new Map();accepted.forEach(d=>sourceCounts.set(d.sourceId,(sourceCounts.get(d.sourceId)||0)+1));const top=[...sourceCounts].sort((a,b)=>b[1]-a[1]).slice(0,6).map(([id])=>id),links=new Map();accepted.forEach(d=>{const a=top.includes(d.sourceId)?source(d.sourceId):'其他渠道',b=names[d.classification.primary];if(!b)return;const key=JSON.stringify([a,'领域 · '+b]);links.set(key,(links.get(key)||0)+1);});const flows=[...links].map(([key,value])=>{const [source,target]=JSON.parse(key);return {source,target,value};});chart('flow-chart',{series:[{type:'sankey',left:10,right:100,top:25,bottom:15,nodeWidth:8,nodeGap:15,draggable:false,emphasis:{focus:'adjacency'},label:{color:document.body.classList.contains('light')?'#335269':'#b7cad9',fontSize:10,width:105,overflow:'truncate'},lineStyle:{color:'source',opacity:.3,curveness:.5},data:[...new Set(flows.flatMap(l=>[l.source,l.target]))].map(name=>({name})),links:flows}]});}
function openDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#detail').showModal();}
listen('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='theme'){document.body.classList.toggle('light');localStorage.setItem('layout-preview-theme',document.body.classList.contains('light')?'light':'dark');if(view==='evidence'&&finished)showSummary();}if(b.id==='close')$('#detail').close();if(b.dataset.tab){tab=b.dataset.tab;page=1;document.querySelectorAll('[data-tab]').forEach(el=>{const selected=el.dataset.tab===tab;el.classList.toggle('active',selected);el.setAttribute('aria-pressed',String(selected));});$('#page-title').textContent='全球信息感知 / '+({channels:'渠道管理',add:'添加订阅',jobs:'同步记录'}[tab]);$('#channel-content').innerHTML=channelContent();}if(b.dataset.channel){channel=b.dataset.channel;page=1;$('#channel-content').innerHTML=channelContent();}if(b.dataset.pageChange){page+=Number(b.dataset.pageChange);$('#channel-table').innerHTML=channelTable();}if(b.dataset.action)runAction(b);if(b.dataset.channelDetail){const s=allChannels().find(s=>String(s.id)===b.dataset.channelDetail);openDialog(s.name,`<p class="tag">${esc(s.type.toUpperCase())}</p><p>${esc(s.note)}</p><p>收录 ${s.count} 篇${s.ready!==null?' · 正文 '+s.ready+' 篇':''}</p><p class="muted">最近时间：${date(s.date)}</p><p>${urlLink(s.url,'访问原始渠道')}</p><button data-action="sync" data-sync-id="${esc(s.id)}" data-sync-type="${esc(s.type)}" class="primary">同步该渠道</button>`);}if(b.dataset.effect){phase=phases.indexOf(b.dataset.effect);effect=b.dataset.effect;step=0;finished=false;paused=false;$('#summary').hidden=true;startReplay();}if(b.id==='pause'){paused=!paused;paintReplay();}if(b.id==='replay'){finished=false;paused=false;step=0;phase=0;effect=phases[0];$('#summary').hidden=true;charts.forEach(c=>c.dispose());charts=[];resize?.disconnect();$('#summary').innerHTML='<div class="pending-summary">正在回放分类结果，结束后展示汇总。</div>';startReplay();}if(b.id==='skip'){completeWorkflow();}if(b.dataset.evidencePage){evidencePageNumber+=Number(b.dataset.evidencePage);$('#evidence-results').innerHTML=evidenceResults();}if(b.dataset.evidence){const d=data.documents.find(d=>d.id===b.dataset.evidence),c=d.classification||{};openDialog('分类依据与原始来源',`<p class="muted">${esc(source(d.sourceId))} · ${date(d.publishedAt)}</p><h3>${esc(d.title)}</h3><div class="classification-tags">${classificationTags(d)}</div><p>${esc(c.reason)}</p><p class="hint">${esc(c.primaryBasis||'原记录未提供主行业判定补充说明')}</p><h3 class="positive-text">正向命中</h3><div class="keyword-list evidence-keywords">${keywordTags(d,'positive')}</div><h3 class="negative-text">反向命中</h3><div class="keyword-list evidence-keywords">${keywordTags(d,'negative')}</div><p class="muted">规则版本：${esc(c.version||'未标注')}</p>${urlLink(d.url,'打开原始文章')}`);}});
listen('input',e=>{if(e.target.id==='evidence-search'){evidenceQuery=e.target.value;evidencePageNumber=1;$('#evidence-results').innerHTML=evidenceResults();}if(e.target.id==='channel-search'){search=e.target.value;page=1;$('#channel-table').innerHTML=channelTable();}});
listen('change',e=>{if(e.target.id==='evidence-page-size'){evidencePageSize=Number(e.target.value);evidencePageNumber=1;$('#evidence-results').innerHTML=evidenceResults();}if(e.target.id==='sector'){sector=e.target.value;evidencePageNumber=1;render();}if(e.target.id==='evidence-source'){sourceFilter=e.target.value;evidencePageNumber=1;render();}});

listen('submit',async e=>{if(e.target.id!=='add-form')return;e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const value=$('#new-source').value.trim();if($('#new-type').value==='rss'){const name=$('#new-name').value.trim();if(!name)throw Error('请填写 RSS 名称');await write('/api/rss/sources',{name,url:value});}else await write('/api/subscriptions/action',{action:'subscribe',articleUrl:value});toast('订阅已提交，正在更新渠道列表');await reloadSources();tab='channels';render();}catch(error){toast(error.message);}finally{button.disabled=false;}});
async function write(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:life.signal});const result=await r.json();if(!r.ok)throw Error(result.message||result.statusMessage||result.error||'操作未完成');return result;}
async function runAction(button){button.disabled=true;try{const type=button.dataset.syncType,id=button.dataset.syncId;if(type==='rss'&&/^\d+$/.test(id))await write('/api/rss/sync',{sourceId:Number(id)});else if(type==='official'||String(id||'').startsWith('intel:'))await write('api/collection',{});else await write('/api/subscriptions/action',{action:button.dataset.action,id:id||undefined});toast('请求已提交，请在同步记录中查看执行状态');await reloadSources();if(tab==='jobs')$('#channel-content').innerHTML=channelContent();}catch(error){toast(error.message);}finally{button.disabled=false;}}
async function reloadSources(){const [subs,rss]=await Promise.all([get('/api/subscriptions'),get('/api/rss/sources')]);Object.assign(data,sourcePayload(subs,rss));}
data=payload;render();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close();},{signal:life.signal});return ()=>{life.abort();clearTimeout(toastTimer);dispose();};
}
